" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"170\" y=\"635\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">RUNG 4 — REDSHIFT (HUBBLE'S LAW)</text><text x=\"170\" y=\"670\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">The most distant observable galaxies</text><text x=\"170\" y=\"698\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">JWST has detected galaxies at z &gt; 14</text><rect x=\"100\" y=\"730\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"170\" y=\"775\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">RUNG 5 — COSMIC MICROWAVE BACKGROUND</text><text x=\"170\" y=\"810\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">The edge of the observable universe</text><text x=\"170\" y=\"838\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Light from 380,000 years after Big Bang</text><rect x=\"200\" y=\"900\" width=\"700\" height=\"140\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"945\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">KEY INSIGHT</text><text x=\"550\" y=\"985\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">No single method covers all distances</text><text x=\"550\" y=\"1018\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Each rung is anchored to the one beneath it</text></svg>",
