      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">YOUR SOLAR SYSTEM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Eight worlds, one ordinary star</text><circle cx=\"120\" cy=\"500\" r=\"50\" fill=\"#ffd700\"/><text x=\"120\" y=\"585\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"18\">Sun</text><circle cx=\"220\" cy=\"500\" r=\"6\" fill=\"#888\"/><text x=\"220\" y=\"585\" text-anchor=\"middle\" fill=\"#888\" font-size=\"14\">Mercury</text><circle cx=\"270\" cy=\"500\" r=\"10\" fill=\"#f59e0b\"/><text x=\"270\" y=\"585\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"14\">Venus</text><circle cx=\"330\" cy=\"500\" r=\"10\" fill=\"#6366f1\"/><text x=\"330\" y=\"585\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"14\">Earth</text><circle cx=\"390\" cy=\"500\" r=\"8\" fill=\"#ef4444\"/><text x=\"390\" y=\"585\" text-anchor=\"middle\" fill=\"#ef4444\" font-size=\"14\">Mars</text><circle cx=\"570\" cy=\"500\" r=\"30\" fill=\"#f59e0b\"/><text x=\"570\" y=\"585\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"14\">Jupiter</text><circle cx=\"720\" cy=\"500\" r=\"26\" fill=\"#ffd700\"/><circle cx=\"720\" cy=\"500\" r=\"36\" fill=\"none\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"720\" y=\"595\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"14\">Saturn</text><circle cx=\"850\" cy=\"500\" r=\"16\" fill=\"#10b981\"/><text x=\"850\" y=\"585\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"14\">Uranus</text><circle cx=\"970\" cy=\"500\" r=\"16\" fill=\"#6366f1\"/><text x=\"970\" y=\"585\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"14\">Neptune</text><rect x=\"80\" y=\"680\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">FOUR ROCKY INNER + FOUR GIANT OUTER</text><text x=\"550\" y=\"770\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Mercury, Venus, Earth, Mars (Terrestrial)</text><text x=\"550\" y=\"805\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Jupiter, Saturn, Uranus, Neptune (Giants)</text><rect x=\"80\" y=\"860\" width=\"940\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"905\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">SAGAN'S COMMITMENT</text><text x=\"550\" y=\"950\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Worked on Mariner, Viking, Voyager, Pioneer</text><text x=\"550\" y=\"985\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Designed Pioneer plaque &amp; Voyager Golden Record</text><text x=\"550\" y=\"1020\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">\"The planets are real places\"</text></svg>",
