" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"695\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">TIME PRESSURE ON EARTH</text><text x=\"550\" y=\"740\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Earth formed 4.5 Gyr ago</text><text x=\"550\" y=\"775\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Earliest life signs: 4.0-3.8 Gyr</text><text x=\"550\" y=\"810\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Life appeared within 500 Myr of habitability — fast</text><rect x=\"80\" y=\"850\" width=\"940\" height=\"190\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"895\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">SAGAN'S QUESTION</text><text x=\"550\" y=\"945\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">\"The question to which the universe</text><text x=\"550\" y=\"985\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">is still working out the answer.\"</text><text x=\"550\" y=\"1025\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">— Carl Sagan, Cosmos</text></svg>",
