" stroke=\"#8b5cf6\" stroke-width=\"2\"/><line x1=\"290\" y1=\"580\" x2=\"460\" y2=\"430\" stroke=\"#10b981\" stroke-width=\"2\"/><line x1=\"810\" y1=\"580\" x2=\"640\" y2=\"430\" stroke=\"#f59e0b\" stroke-width=\"2\"/><line x1=\"550\" y1=\"640\" x2=\"550\" y2=\"520\" stroke=\"#ec4899\" stroke-width=\"2\"/><rect x=\"80\" y=\"800\" width=\"940\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"845\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">PROCESS</text><text x=\"550\" y=\"885\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Your words. Connect sections. Add 3 questions.</text><text x=\"550\" y=\"915\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Date it. Revisit in 1 year.</text><rect x=\"200\" y=\"950\" width=\"700\" height=\"90\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"995\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">YOUR UNDERSTANDING</text><text x=\"550\" y=\"1030\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">is one of your most valuable possessions</text></svg>",
      "caption": "A personal knowledge map of the cosmos"
